 ('Rallye in der Wüste', 'Sport & Action', 'Setze die Personen als Rallye-Fahrer neben einen staubigen Geländewagen in der Wüste mit Dünen. Ganzkörperaufnahme mit sichtbaren Händen. Behalte Gesichter, Frisuren und Körperhaltung erkennbar. Fotorealistisch.'),
 ('Dschungel-Expedition', 'Sport & Action', 'Setze die Personen als Abenteurer mit Macheten und Taschenlampen in eine Tempelruine im Dschungel. Ganzkörperaufnahme mit sichtbaren Händen. Behalte Gesichter, Frisuren und Körperhaltung erkennbar. Fotorealistisch.'),
 ('Eiskletterer', 'Sport & Action', 'Setze die Personen mit Eispickeln an eine gefrorene Wasserfallwand in den Bergen. Ganzkörperaufnahme mit sichtbaren Händen. Behalte Gesichter, Frisuren und Körperhaltung erkennbar. Fotorealistisch.')
)
insert into public.ai_styles (owner, name, prompt, category, shared)
select p.id, n.name, n.prompt, n.category, true
  from neu n cross join (select id from public.profiles where is_admin order by created_at limit 1) p
 where not exists (select 1 from public.ai_styles s where s.owner = p.id and s.name = n.name);
